  "Esta APK não tem o mapa Google configurado. Mostramos um esquema geográfico simplificado e seguro; o mapa com ruas requer uma APK com a chave da SDK Android.": "This APK has no Google map configured. We show a simplified, safe geographic view; the street map needs an APK with the Android SDK key.",
