  "Esta ação é definitiva.": "This is permanent.",
  "Esta ação é definitiva. A classificação final e os resultados ficam arquivados e não poderão ser alterados.": "This is permanent. The final standings and results are archived and can't be changed.",
  "Esta ação é definitiva. Só é possível eliminar uma equipa sem jogadores convidados, mensagens, competições ou histórico. O servidor protege todos esses dados.": "This is permanent. A team can only be deleted with no invited players, messages, competitions or history. The server protects all that data.",
  "Esta ação é irreversível. Os dados pessoais serão apagados ou anonimizados. Se tens comunidades próprias, transfere primeiro a propriedade.": "This cannot be undone. Personal data will be deleted or anonymised. If you own communities, transfer ownership first.",
